from pathlib import Path
D=Path(__file__).resolve().parent/'docs';p=D/'projects/delivery-drone/index.html';s=p.read_text(encoding='utf-8')
block='''<section class="section" id="mission-evidence"><div class="section-title"><h2>Delivery mission evidence</h2></div><div class="delivery-metrics"><div><strong>20.25 km</strong><span>Total out-and-return GPS travel</span></div><div><strong>10.11 km</strong><span>Maximum displacement from arming</span></div><div><strong>35.67 min</strong><span>Armed mission interval</span></div><div><strong>5 kg</strong><span>Rice payload, project-owner confirmed</span></div></div><div class="links"><a class="btn" href="../../reports/delivery-drone-flight-review.pdf" target="_blank" rel="noopener">Read the eight-page flight report</a><a href="../../blog/delivery-drone-distance-release/">Read the project story</a></div><p>GPS-position integration is cross-checked against groundspeed. The report separates the early commissioning file from the matching long-distance mission, with release, control, vibration and failsafe evidence.</p></section><section class="section" id="remote-field-support"><div class="section-title"><h2>Remote field support</h2></div><figure><video controls playsinline controlslist="nodownload noremoteplayback" disablepictureinpicture preload="none" poster="../../media/delivery-drone/remote-support-full.webp" style="max-width:100%;height:480px;background:#111"><source src="../../media/delivery-drone/remote-field-support-full.mp4" type="video/mp4">Your browser does not support inline video.</video><figcaption>Live setup and field-test guidance with the on-site operator. Original portrait video-call framing, with Achraf visible providing remote guidance to the on-site operator. Muted web copy; not footage of the 20 km mission.</figcaption></figure></section><section class="section"><div class="section-title"><h2>Separate heavy-lift projects</h2></div><div class="links"><a href="../heavy-lift/">DARPA Lift Challenge team support</a><a href="../drone-rover-docking/">Drone-to-rover docking system</a></div><p>These are different aircraft and engagements. Their photographs, validation and engineering stories remain in their own project records.</p></section>'''
anchor='<section class="section"><div class="section-title"><h2>Project photographs</h2>'
assert anchor in s;s=s.replace(anchor,block+anchor,1);s=s.replace('</head>','<style>.delivery-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;border-block:1px solid var(--line);padding:25px 0;margin:25px 0}.delivery-metrics strong{display:block;font:30px Georgia,serif;color:var(--accent)}.delivery-metrics span{display:block;font-size:12px;color:var(--muted);margin-top:10px}@media(max-width:650px){.delivery-metrics{grid-template-columns:1fr 1fr}}</style></head>');p.write_text(s,encoding='utf-8')
print('Added delivery evidence, matching support clip and separate heavy-lift links.')
